        match = True
    if eid.startswith('bf16_'):
        match = True
    if 'ppl' in eid.lower():
        match = True
    exp_str = json.dumps(exp).lower()
    if 'ppl' in exp_str or 'perplexity' in exp_str or 'dose' in exp_str:
