# Sort into groups
groups = {
    'v6_importance': [],
    'v6_random': [],
    'bf16_ds_imp': [],
    'bf16_ds_rand': [],
    'bf16_qw_imp': [],
    'bf16_qw_rand': [],
    'bf16_importance (early)': [],
    'bf16_random (early)': [],
    'bf16_qwen_importance (early)': [],
    'n500_unified': [],
    'mvp_v5_fixed': [],
    'mvp_v5_random': [],
    'mvp_v4_legacy': [],
    'other': [],
}

for eid in sorted(ppl_ids):
    placed = False
    if eid.startswith('v6_importance'):
        groups['v6_importance'].append(eid); placed = True
    elif eid.startswith('v6_random'):
        groups['v6_random'].append(eid); placed = True
    elif eid.startswith('bf16_ds_imp'):
        groups['bf16_ds_imp'].append(eid); placed = True
    elif eid.startswith('bf16_ds_rand'):
        groups['bf16_ds_rand'].append(eid); placed = True
    elif eid.startswith('bf16_qw_imp'):
        groups['bf16_qw_imp'].append(eid); placed = True
    elif eid.startswith('bf16_qw_rand'):
        groups['bf16_qw_rand'].append(eid); placed = True
    elif eid.startswith('bf16_importance'):
        groups['bf16_importance (early)'].append(eid); placed = True
    elif eid.startswith('bf16_random'):
        groups['bf16_random (early)'].append(eid); placed = True
    elif eid.startswith('bf16_qwen_importance'):
        groups['bf16_qwen_importance (early)'].append(eid); placed = True
    elif 'n500' in eid:
        groups['n500_unified'].append(eid); placed = True
    elif eid.startswith('mvp_v5_fixed'):
        groups['mvp_v5_fixed'].append(eid); placed = True
    elif eid.startswith('mvp_v5_random'):
        groups['mvp_v5_random'].append(eid); placed = True
    elif eid.startswith('mvp_v4_legacy'):
        groups['mvp_v4_legacy'].append(eid); placed = True
    if not placed:
        groups['other'].append(eid)

# Now print ALL experiments with full details
for group_name, eids in groups.items():
    if not eids:
        continue
    print(f"\n{'='*80}")
    print(f"GROUP: {group_name} ({len(eids)} experiments)")
    print(f"{'='*80}")

    for eid in eids:
        exp = experiments[eid]
        print(f"\n--- {eid} ---")
        print(f"  status: {exp.get('status')}")
        print(f"  conclusion: {exp.get('conclusion')}")
        print(f"  hypothesis: {exp.get('hypothesis', 'N/A')}")

        # Spec details
        spec = exp.get('spec', {})
        if spec.get('model_name'):
            print(f"  model: {spec['model_name']}")
        if spec.get('data_count'):
            print(f"  data_count: {spec['data_count']}")
        if spec.get('gpu'):
            print(f"  gpu: {spec['gpu']}")
        if spec.get('wall_clock_seconds'):
            print(f"  wall_clock_seconds: {spec['wall_clock_seconds']}")
        if spec.get('gpu_hours'):
            print(f"  gpu_hours: {spec['gpu_hours']}")

        # Metrics - print ALL
        metrics = exp.get('metrics', {})
        if metrics:
            print(f"  metrics:")
            for mk, mv in metrics.items():
                print(f"    {mk}: {mv}")
        else:
            print(f"  metrics: (none)")

        # Notes
        if exp.get('notes'):
            print(f"  notes: {exp['notes']}")

        print()

